-- All fixtures and document metadata below are synthetic and rolled back.
BEGIN;
SET LOCAL statement_timeout='40s';
CREATE TEMP TABLE portal_qa(label text,passed boolean);
GRANT ALL ON portal_qa TO service_role;
SET LOCAL ROLE service_role;
DO $$
DECLARE w uuid;actor uuid;email text;t uuid:=gen_random_uuid();c uuid:=gen_random_uuid();ft uuid:=gen_random_uuid();f uuid;r uuid;u jsonb;claim uuid:=gen_random_uuid();i public.case_participant_invitations;other public.case_participant_invitations;payload jsonb;meta jsonb;op uuid:=gen_random_uuid();blocked boolean;tok jsonb;token_row public.form_tokens;response uuid:=gen_random_uuid();
BEGIN
 SELECT m.workspace_id,m.user_id INTO w,actor FROM public.workspace_members m JOIN public.workspaces ws ON ws.id=m.workspace_id WHERE m.status='active' AND m.role='owner' AND (m.access_expires_at IS NULL OR m.access_expires_at>now()) AND coalesce((ws.organization_settings#>>'{case_review,separationOfDuties}')::boolean,false)=false LIMIT 1;
 SELECT p.email INTO email FROM public.user_profiles p WHERE id=actor;
 IF w IS NULL OR email IS NULL THEN RAISE EXCEPTION 'QA_NO_WORKSPACE';END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 INSERT INTO public.form_templates(id,workspace_id,name,status,created_by,requires_signature,settings,schema) VALUES(ft,w,'QA PORTAL ROLLBACK','draft',actor,false,'{"requiresSignature":false}','[{"id":"signature","type":"signature_block","required":true}]');
 UPDATE public.form_templates SET status='published' WHERE id=ft;
 payload:=jsonb_build_object('name','QA PORTAL ROLLBACK','description','','case_type','QA','requirements_schema',jsonb_build_object('version',6,'workflowMode','simple','sections',jsonb_build_array(jsonb_build_object('id','section','title','QA','items',jsonb_build_array(jsonb_build_object('id','item','kind','requested_document','title','Documento QA','required',true,'requiresReview',true,'reviewerRole','owner','requiresSignature',false,'allowedFormats',jsonb_build_array('pdf'),'maxSizeMb',15,'allowReplacement',true),jsonb_build_object('id','form','kind','form','title','Formulario QA','sourceId',ft,'sourceVersion','1','sourceRevision',1,'required',true,'requiresReview',false,'requiresSignature',false)))),'verifications','[]'::jsonb,'stages','[]'::jsonb,'reviewPolicy',jsonb_build_object('version',1,'reviewTiming','progressive','approval',jsonb_build_object('enabled',false,'role',null),'completion',jsonb_build_object('mode','manual','role','owner'))),'forms_schema','[]'::jsonb);
 PERFORM public.case_control_publish(t,actor,w,null,payload);
 PERFORM public.case_launch_invited(t,actor,'QA PORTAL','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),c,email,jsonb_build_array(jsonb_build_object('name','Otro QA','email','other@example.invalid','role','contact')),jsonb_build_array(jsonb_build_object('hash',repeat('a',64),'ciphertext',repeat('x',100)),jsonb_build_object('hash',repeat('b',64),'ciphertext',repeat('y',100))),'https://example.invalid');
 SELECT * INTO i FROM public.case_participant_invitations WHERE case_file_id=c AND participant_role='subject';
 SELECT * INTO other FROM public.case_participant_invitations WHERE case_file_id=c AND participant_role='contact';
 SELECT id INTO r FROM public.case_file_requirements WHERE case_file_id=c;
 SELECT id INTO f FROM public.case_file_forms WHERE case_file_id=c;
 meta:=jsonb_build_object('name','qa.pdf','mime','application/pdf','size',1024,'sha256',repeat('c',64),'keyCiphertext','encrypted-test-only','nonce','test-only');
 u:=public.case_portal_prepare_upload(i.token_hash,r,op,meta);
 IF public.case_portal_prepare_upload(i.token_hash,r,op,meta)->>'id'<>u->>'id' THEN RAISE EXCEPTION 'QA_DUPLICATE_PREPARE';END IF;
 INSERT INTO portal_qa VALUES('preparation is retry safe',true);
 blocked:=false;BEGIN PERFORM public.case_portal_prepare_upload(other.token_hash,r,gen_random_uuid(),meta);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_CROSS_PARTICIPANT';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_claim_upload(other.token_hash,(u->>'id')::uuid,claim,'qa/rollback.pdf');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_CROSS_RECEIPT';END IF;
 INSERT INTO portal_qa VALUES('another participant cannot prepare or finalize a document',true);
 PERFORM public.case_portal_claim_upload(i.token_hash,(u->>'id')::uuid,claim,'qa/rollback.pdf');
 blocked:=false;BEGIN PERFORM public.case_portal_claim_upload(i.token_hash,(u->>'id')::uuid,gen_random_uuid(),'qa/rollback.pdf');EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_UPLOAD_BUSY' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_CONCURRENT_UPLOAD';END IF;
 INSERT INTO portal_qa VALUES('active upload lease prevents concurrent finalization',true);
 PERFORM public.case_portal_commit_upload(i.token_hash,(u->>'id')::uuid,claim);
 PERFORM public.case_portal_commit_upload(i.token_hash,(u->>'id')::uuid,claim);
 IF (SELECT count(*) FROM public.case_file_document_versions WHERE case_file_id=c)<>1 OR (SELECT status FROM public.case_file_requirements WHERE id=r)<>'uploaded' OR (SELECT deleted_at FROM public.documentos WHERE id=(u->>'document_id')::uuid) IS NOT NULL THEN RAISE EXCEPTION 'QA_DOCUMENT_RECEIPT';END IF;
 IF EXISTS(SELECT 1 FROM public.case_file_reviews WHERE case_file_id=c) OR (SELECT status FROM public.case_files WHERE id=c)='sealed' THEN RAISE EXCEPTION 'QA_FALSE_APPROVAL';END IF;
 INSERT INTO portal_qa VALUES('document receipt is atomic, versioned and does not approve or close',true);
 tok:=public.case_portal_form_token(i.token_hash,f);
 IF tok->>'token' IS DISTINCT FROM public.case_portal_form_token(i.token_hash,f)->>'token' THEN RAISE EXCEPTION 'QA_DUPLICATE_FORM_TOKEN';END IF;
 SELECT * INTO token_row FROM public.form_tokens WHERE token=tok->>'token';
 IF token_row.access_mode<>'private' OR token_row.recipient_email<>email OR token_row.expires_at>i.expires_at THEN RAISE EXCEPTION 'QA_FORM_TOKEN_SCOPE';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_form_token(other.token_hash,f);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_OTHER_FORM';END IF;
 INSERT INTO portal_qa VALUES('private form token is scoped to the assigned participant and invitation',true);
 INSERT INTO public.form_responses(id,token_id,template_id,workspace_id,response_data,field_hashes,respondent_email,submitted_at,status) VALUES(response,token_row.id,ft,w,'{"qa":"synthetic"}','{}',email,now(),'started');
 UPDATE public.form_tokens SET used_at=now() WHERE id=token_row.id;
 UPDATE public.form_responses SET pdf_output_hash=repeat('d',64),status='pdf_generated' WHERE id=response;
 IF NOT EXISTS(SELECT 1 FROM public.case_file_form_submissions WHERE case_form_id=f AND form_response_id=response AND submitted_at IS NOT NULL) THEN RAISE EXCEPTION 'QA_FORM_AUTO_BIND';END IF;
 UPDATE public.form_responses SET status='pdf_generated' WHERE id=response;
 IF (SELECT count(*) FROM public.case_file_form_submissions WHERE case_form_id=f)<>1 THEN RAISE EXCEPTION 'QA_DUPLICATE_FORM_BIND';END IF;
 IF public.case_portal_form_token(i.token_hash,f)->>'token'<>tok->>'token' OR NOT (public.case_portal_form_token(i.token_hash,f)->>'resume')::boolean THEN RAISE EXCEPTION 'QA_RESUME_RECEIPT';END IF;
 blocked:=false;BEGIN UPDATE public.form_responses SET token_id=gen_random_uuid() WHERE id=response;EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_FORM_RECEIPT_IMMUTABLE' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_UNBOUND_RECEIPT';END IF;
 blocked:=false;BEGIN DELETE FROM public.form_responses WHERE id=response;EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_FORM_RECEIPT_IMMUTABLE' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_RECEIPT_DELETION';END IF;
 blocked:=false;BEGIN UPDATE public.form_responses SET pdf_output_hash=repeat('e',64) WHERE id=response;EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_FORM_RECEIPT_IMMUTABLE' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_RECEIPT_OVERWRITE';END IF;
 INSERT INTO portal_qa VALUES('used form resumes the same receipt and cannot be unbound or deleted',true);
 INSERT INTO portal_qa VALUES('canonical form PDF automatically binds once and queues progress refresh',true);
 DECLARE c2 uuid:=gen_random_uuid(); f2 uuid; child jsonb; tok2 public.form_tokens; BEGIN
  PERFORM public.case_launch_invited(t,actor,'QA SECOND CASE','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),c2,email,'[]',jsonb_build_array(jsonb_build_object('hash',repeat('9',64),'ciphertext',repeat('z',100))),'https://example.invalid');
  SELECT id INTO f2 FROM public.case_file_forms WHERE case_file_id=c2;
  child:=public.case_portal_form_token(repeat('9',64),f2);
  SELECT * INTO tok2 FROM public.form_tokens WHERE token=child->>'token';
  INSERT INTO public.form_responses(token_id,template_id,workspace_id,response_data,field_hashes,respondent_email,submitted_at,status) VALUES(tok2.id,ft,w,'{"qa":"second invitation"}','{}',email,now(),'started');
  INSERT INTO portal_qa VALUES('same participant may answer the same private form in another case',true);
 END;
 PERFORM public.case_invitation_manage(c,actor,i.id,'revoke',gen_random_uuid(),'{}');
 IF (SELECT expires_at FROM public.form_tokens WHERE id=token_row.id)>now() THEN RAISE EXCEPTION 'QA_CHILD_TOKEN_REVOCATION';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_prepare_upload(i.token_hash,r,gen_random_uuid(),meta);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_REVOKED_UPLOAD';END IF;
 INSERT INTO portal_qa VALUES('revoking invitation also revokes its forms and uploads',true);
 IF has_table_privilege('authenticated','public.case_portal_uploads','SELECT') OR has_function_privilege('anon','public.case_portal_context(text,boolean)','EXECUTE') OR has_table_privilege('authenticated','public.case_portal_form_tokens','SELECT') THEN RAISE EXCEPTION 'QA_PUBLIC_ACCESS';END IF;
 INSERT INTO portal_qa VALUES('Data API cannot read capabilities or invoke privileged portal operations',true);
END;$$;
RESET ROLE;
SELECT * FROM portal_qa;
ROLLBACK;
